CREATE OR REPLACE FUNCTION public.post_media_source_key(_url text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public,extensions AS $$ SELECT CASE WHEN coalesce(_url,'') ~ '/post-media-cache/posts/[a-fA-F0-9]{40}\.' THEN lower(substring(_url FROM '/post-media-cache/posts/([a-fA-F0-9]{40})\.')) WHEN _url ~* '^https?://' THEN encode(extensions.digest(lower(substring(_url FROM '^https?://([^/]+)')) || split_part(split_part(regexp_replace(_url,'^https?://[^/]+',''), '?',1),'#',1),'sha1'),'hex') ELSE split_part(split_part(trim(coalesce(_url,'')),'?',1),'#',1) END $$;
CREATE OR REPLACE FUNCTION public.dedupe_media_jsonb(_arr jsonb,_blocked jsonb DEFAULT '[]'::jsonb) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE item jsonb; url text; k text; seen text[]:=ARRAY[]::text[]; output jsonb:='[]'; BEGIN IF _arr IS NULL OR jsonb_typeof(_arr)<>'array' THEN RETURN _arr; END IF; FOR item IN SELECT value FROM jsonb_array_elements(_arr) LOOP url:=CASE WHEN jsonb_typeof(item)='string' THEN item#>>'{}' ELSE coalesce(item->>'url',item->>'src','') END; k:=public.post_media_source_key(url); IF k='' OR k=ANY(seen) OR (jsonb_typeof(_blocked)='array' AND _blocked ? public.media_dedupe_key(url)) THEN CONTINUE; END IF; seen:=array_append(seen,k); output:=output||jsonb_build_array(item); END LOOP; RETURN output; END $$;
CREATE OR REPLACE FUNCTION public.trg_dedupe_draft_media() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.media_urls:=public.dedupe_media_jsonb(NEW.media_urls); RETURN NEW; END $$;
CREATE TRIGGER dedupe_draft_media BEFORE INSERT OR UPDATE OF media_urls ON public.ai_content_logs FOR EACH ROW EXECUTE FUNCTION public.trg_dedupe_draft_media();